export const categoryMap = {
  electrical: '电气',
  plumbing: '水暖',
  furniture: '家具',
  door_window: '门窗',
  floor: '地面',
  wall: '墙面',
  other: '其他'
}

export const categoryOptions = Object.entries(categoryMap).map(([value, label]) => ({ label, value }))

export const priorityMap = {
  low: '低',
  medium: '中',
  high: '高',
  urgent: '紧急'
}

export const priorityOptions = Object.entries(priorityMap).map(([value, label]) => ({ label, value }))

export const priorityType = {
  low: 'info',
  medium: '',
  high: 'warning',
  urgent: 'danger'
}

export const statusMap = {
  pending: '待处理',
  processing: '处理中',
  completed: '已完成',
  rejected: '已驳回'
}

export const statusOptions = Object.entries(statusMap).map(([value, label]) => ({ label, value }))

export const statusType = {
  pending: 'warning',
  processing: '',
  completed: 'success',
  rejected: 'danger'
}

export const roleMap = {
  admin: '管理员',
  teacher: '教师',
  student: '学生',
  maintenance: '维修人员'
}
